/* ===== Reset & Base ===== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  background: #f0f2f5;
  color: #2c3e50;
  min-height: 100vh;
}

/* ===== Page Layout ===== */
.page {
  padding: 24px 28px;
}

.page-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: #1a1a2e;
  margin-bottom: 6px;
  letter-spacing: -0.01em;
}

.page-subtitle {
  font-size: 0.85rem;
  color: #6c757d;
  margin-bottom: 20px;
}

.main-layout {
  display: flex;
  gap: 24px;
  align-items: flex-start;
}

/* ===== Chart Panel ===== */
.chart-panel {
  flex: 0 0 auto;
}

.panel-heading {
  font-size: 0.95rem;
  font-weight: 600;
  color: #344054;
  margin-bottom: 10px;
  padding-left: 2px;
}

#bubble-chart {
  display: block;
  background: #ffffff;
  border-radius: 10px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.08), 0 4px 16px rgba(0,0,0,0.06);
}

/* ===== Bubble Styles ===== */
.bubble {
  cursor: pointer;
  transition: opacity 0.15s;
}

.bubble:hover {
  opacity: 0.85;
}

.bubble.selected {
  stroke: #f5c518 !important;
  stroke-width: 3px !important;
}

text.tick-label {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  font-weight: 600;
  letter-spacing: 0.01em;
  pointer-events: none;
  user-select: none;
}

/* ===== Legend ===== */
#legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 18px;
  margin-top: 12px;
  padding: 10px 14px;
  background: #ffffff;
  border-radius: 8px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.07);
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 7px;
}

.legend-swatch {
  width: 13px;
  height: 13px;
  border-radius: 3px;
  flex-shrink: 0;
}

.legend-label {
  font-size: 0.76rem;
  color: #4a5568;
  font-weight: 500;
  white-space: nowrap;
}

/* ===== Table Panel ===== */
.table-panel {
  flex: 1;
  min-width: 0;
}

.table-scroll {
  max-height: 730px;
  overflow-y: auto;
  border-radius: 10px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.08), 0 4px 16px rgba(0,0,0,0.06);
  background: #ffffff;
}

/* Scrollbar styling */
.table-scroll::-webkit-scrollbar {
  width: 6px;
}
.table-scroll::-webkit-scrollbar-track {
  background: #f1f3f5;
}
.table-scroll::-webkit-scrollbar-thumb {
  background: #ced4da;
  border-radius: 3px;
}
.table-scroll::-webkit-scrollbar-thumb:hover {
  background: #adb5bd;
}

#stock-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.81rem;
}

#stock-table thead {
  position: sticky;
  top: 0;
  z-index: 2;
  background: #1a1a2e;
  color: #e9ecef;
}

#stock-table th {
  padding: 11px 14px;
  text-align: left;
  font-weight: 500;
  font-size: 0.75rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  white-space: nowrap;
}

#stock-table td {
  padding: 8px 14px;
  border-bottom: 1px solid #f1f3f5;
  vertical-align: middle;
}

#stock-table td:first-child {
  font-weight: 700;
  color: #1a1a2e;
  font-size: 0.82rem;
  white-space: nowrap;
}

#stock-table td:last-child {
  font-variant-numeric: tabular-nums;
  text-align: right;
  color: #2d6a4f;
  font-weight: 600;
  white-space: nowrap;
}

.stock-row {
  cursor: pointer;
  transition: background 0.1s;
}

.stock-row:hover {
  background: #f0f4ff;
}

.stock-row.selected {
  background: #e8f0fe;
}

.stock-row.selected td:first-child {
  color: #1a56db;
}

/* Sector badge in table */
.sector-badge {
  display: inline-block;
  padding: 2px 7px;
  border-radius: 10px;
  font-size: 0.7rem;
  font-weight: 500;
  white-space: nowrap;
}

/* ===== Tooltip ===== */
.tooltip {
  position: fixed;
  padding: 9px 13px;
  background: rgba(20, 20, 40, 0.93);
  color: #f8f9fa;
  border-radius: 7px;
  font-size: 0.78rem;
  line-height: 1.55;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.12s;
  z-index: 9999;
  max-width: 230px;
  box-shadow: 0 4px 14px rgba(0,0,0,0.25);
}

.tooltip.visible {
  opacity: 1;
}

.tooltip-ticker {
  font-size: 0.9rem;
  font-weight: 700;
  margin-bottom: 3px;
  color: #ffffff;
}

.tooltip-name {
  color: #ced4da;
  margin-bottom: 2px;
}

.tooltip-sector {
  color: #adb5bd;
  font-size: 0.72rem;
}

(function () {
  'use strict';

  // ── Configuration ────────────────────────────────────────────────────────────
  var CHART_W = 820;
  var CHART_H = 720;
  var MAX_RADIUS = 56;
  var MIN_RADIUS = 8;
  var ETF_RADIUS = 16;
  var SIM_TICKS = 400;

  // Deterministic sector order
  var SECTOR_ORDER = [
    'Information Technology',
    'Industry',
    'Energy',
    'Financial',
    'ETF'
  ];

  // Sector fill colors
  var SECTOR_COLORS = {
    'Information Technology': '#4e79a7',
    'Industry':               '#f28e2b',
    'Energy':                 '#59a14f',
    'Financial':              '#b07aa1',
    'ETF':                    '#76b7b2'
  };

  // Sector badge background (lighter tint of each color)
  var SECTOR_BG = {
    'Information Technology': '#dce9f5',
    'Industry':               '#fde8cc',
    'Energy':                 '#d4edda',
    'Financial':              '#ecdcf5',
    'ETF':                    '#d4eeec'
  };

  // Cluster target centers for forceX / forceY
  var CLUSTER_CENTERS = {
    'Information Technology': { x: 185, y: 190 },
    'Industry':               { x: 635, y: 190 },
    'ETF':                    { x: 410, y: 370 },
    'Energy':                 { x: 185, y: 555 },
    'Financial':              { x: 635, y: 555 }
  };

  // ── Helpers ──────────────────────────────────────────────────────────────────
  function formatMarketCap(val) {
    if (val == null) return '\u2014';
    var num = parseFloat(val);
    if (isNaN(num) || num === 0) return '\u2014';
    if (num >= 1e12) return (num / 1e12).toFixed(2) + 'T';
    if (num >= 1e9)  return (num / 1e9).toFixed(2) + 'B';
    if (num >= 1e6)  return (num / 1e6).toFixed(2) + 'M';
    return num.toFixed(0);
  }

  function tickerFontSize(r) {
    if (r >= 35) return '11px';
    if (r >= 24) return '9px';
    if (r >= 16) return '7px';
    return '6px';
  }

  // ── Main ─────────────────────────────────────────────────────────────────────
  d3.json('./data/stock-descriptions.json').then(function (raw) {

    // Process & sort deterministically by ticker
    var stocks = raw.map(function (d) {
      var cap = (d.marketCap && d.marketCap !== '') ? parseFloat(d.marketCap) : null;
      return {
        ticker:    d.ticker,
        name:      d['full name'],
        sector:    d.sector,
        marketCap: cap,
        isETF:     d.sector === 'ETF'
      };
    });
    stocks.sort(function (a, b) { return a.ticker < b.ticker ? -1 : 1; });

    // Compute radii
    var maxCap = d3.max(stocks, function (d) { return d.marketCap || 0; });
    var rScale = d3.scaleSqrt().domain([0, maxCap]).range([0, MAX_RADIUS]);

    stocks.forEach(function (d) {
      if (d.isETF) {
        d.r = ETF_RADIUS;
      } else {
        d.r = Math.max(MIN_RADIUS, rScale(d.marketCap || 0));
      }
    });

    // Deterministic initial positions: spread around cluster center
    var sectorIdx = {};
    SECTOR_ORDER.forEach(function (s) { sectorIdx[s] = 0; });
    stocks.forEach(function (d) {
      var i = sectorIdx[d.sector]++;
      var c = CLUSTER_CENTERS[d.sector];
      var angle = i * (2 * Math.PI / 10);
      d.x = c.x + (d.r + 8) * Math.cos(angle);
      d.y = c.y + (d.r + 8) * Math.sin(angle);
    });

    // Force simulation (deterministic: fixed ticks, no animation)
    var sim = d3.forceSimulation(stocks)
      .force('x', d3.forceX(function (d) { return CLUSTER_CENTERS[d.sector].x; }).strength(0.13))
      .force('y', d3.forceY(function (d) { return CLUSTER_CENTERS[d.sector].y; }).strength(0.13))
      .force('collide', d3.forceCollide(function (d) { return d.r + 1.5; }).iterations(5))
      .stop();

    for (var t = 0; t < SIM_TICKS; t++) { sim.tick(); }

    // Clamp to SVG bounds
    stocks.forEach(function (d) {
      d.x = Math.max(d.r + 4, Math.min(CHART_W - d.r - 4, d.x));
      d.y = Math.max(d.r + 4, Math.min(CHART_H - d.r - 4, d.y));
    });

    // ── Build SVG bubble chart ─────────────────────────────────────────────────
    var svg = d3.select('#bubble-chart')
      .attr('width', CHART_W)
      .attr('height', CHART_H);

    // Bubbles — the ONLY <circle> elements in the document
    var circles = svg.selectAll('circle')
      .data(stocks, function (d) { return d.ticker; })
      .join('circle')
        .attr('id',    function (d) { return 'bubble-' + d.ticker; })
        .attr('class', 'bubble')
        .attr('cx',    function (d) { return d.x; })
        .attr('cy',    function (d) { return d.y; })
        .attr('r',     function (d) { return d.r; })
        .attr('fill',  function (d) { return SECTOR_COLORS[d.sector]; })
        .attr('stroke', '#ffffff')
        .attr('stroke-width', 1.5);

    // Ticker labels inside bubbles
    svg.selectAll('text.tick-label')
      .data(stocks, function (d) { return d.ticker; })
      .join('text')
        .attr('class', 'tick-label')
        .attr('x', function (d) { return d.x; })
        .attr('y', function (d) { return d.y; })
        .attr('text-anchor', 'middle')
        .attr('dominant-baseline', 'central')
        .attr('font-size', function (d) { return tickerFontSize(d.r); })
        .attr('fill', '#ffffff')
        .text(function (d) { return d.ticker; });

    // ── Tooltip ────────────────────────────────────────────────────────────────
    var tooltip = d3.select('#tooltip');

    circles
      .on('mouseover', function (event, d) {
        if (d.isETF) return;
        tooltip
          .classed('visible', true)
          .html(
            '<div class="tooltip-ticker">' + d.ticker + '</div>' +
            '<div class="tooltip-name">' + d.name + '</div>' +
            '<div class="tooltip-sector">' + d.sector + '</div>'
          )
          .style('left', (event.clientX + 14) + 'px')
          .style('top',  (event.clientY - 10) + 'px');
      })
      .on('mousemove', function (event, d) {
        if (d.isETF) return;
        tooltip
          .style('left', (event.clientX + 14) + 'px')
          .style('top',  (event.clientY - 10) + 'px');
      })
      .on('mouseout', function () {
        tooltip.classed('visible', false);
      })
      .on('click', function (event, d) {
        selectStock(d.ticker, 'bubble');
      });

    // ── Legend (div-based, no SVG circles) ────────────────────────────────────
    var legendEl = d3.select('#legend');
    SECTOR_ORDER.forEach(function (sector) {
      var item = legendEl.append('div').attr('class', 'legend-item');
      item.append('div')
        .attr('class', 'legend-swatch')
        .style('background-color', SECTOR_COLORS[sector]);
      item.append('span')
        .attr('class', 'legend-label')
        .text(sector);
    });

    // ── Data table ─────────────────────────────────────────────────────────────
    var tbody = d3.select('#stock-table tbody');

    var rows = tbody.selectAll('tr')
      .data(stocks, function (d) { return d.ticker; })
      .join('tr')
        .attr('id',    function (d) { return 'row-' + d.ticker; })
        .attr('class', 'stock-row')
        .on('click', function (event, d) {
          selectStock(d.ticker, 'row');
        });

    rows.append('td').text(function (d) { return d.ticker; });
    rows.append('td').text(function (d) { return d.name; });
    rows.append('td').each(function (d) {
      var badge = document.createElement('span');
      badge.className = 'sector-badge';
      badge.textContent = d.sector;
      badge.style.backgroundColor = SECTOR_BG[d.sector] || '#e9ecef';
      badge.style.color = d3.color(SECTOR_COLORS[d.sector]).darker(0.6).formatHex();
      this.appendChild(badge);
    });
    rows.append('td').text(function (d) { return formatMarketCap(d.marketCap); });

    // ── Selection / highlight logic ────────────────────────────────────────────
    function selectStock(ticker, source) {
      // Reset all bubbles
      d3.selectAll('.bubble')
        .classed('selected', false)
        .attr('stroke', '#ffffff')
        .attr('stroke-width', 1.5);

      // Highlight selected bubble
      d3.select('#bubble-' + ticker)
        .classed('selected', true)
        .attr('stroke', '#f5c518')
        .attr('stroke-width', 3);

      // Reset all rows
      d3.selectAll('.stock-row').classed('selected', false);

      // Highlight selected row
      d3.select('#row-' + ticker).classed('selected', true);

      // Scroll the table row into view when bubble clicked
      if (source === 'bubble') {
        var rowEl = document.getElementById('row-' + ticker);
        if (rowEl) {
          rowEl.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        }
      }

      // Scroll bubble into view when row clicked (no-op here, chart is fixed)
    }

  }).catch(function (err) {
    console.error('Failed to load stock data:', err);
    document.getElementById('loading-msg').textContent =
      'Error loading data: ' + err.message;
  });

}());
